def _specs() -> dict[str, dict[str, Any]]:
    # Parse the embedded pinned table. / 解析内嵌钉死表。
    return json.loads(SPECS_JSON)


COVERED_MODULES: tuple[str, ...] = tuple(sorted(_specs()))


def parse_width(width: str) -> int:
    # Convert an ANSI width token to a bit count. / 把 ANSI 位宽记号转为比特数。
    token = (width or "").strip().strip("[]")
    if not token:
        return 1
    if ":" in token:
        high = token.split(":")[0]
        return int(high) + 1
    return int(token)


def family_of(name: str) -> str:
    # Classify a covered module into its behavior family. / 按锁定名归类行为家族。
    if name.startswith("FuBusyTableWrite"):
        return "FuBusyTableWrite"
    if name == "WbFuBusyTable":
        return "WbFuBusyTable"
    if name.startswith("DiffExtArch"):
        return "DifftestRat"
    if name == "RenameTableWrapper":
        return "RenameTableWrapper"
    if name.startswith("RenameTable"):
        return "RenameTable"
    if "RegFilePart" in name or name == "VlRegFile":
        return "RegFilePart"
    if name.startswith(("IntRFReadArbiter", "FpRFReadArbiter", "VfRFReadArbiter",
                        "V0RFReadArbiter", "VlRFReadArbiter")):
        return "RFReadArbiter"
    if name.startswith(("IntRFWBCollideChecker", "FpRFWBCollideChecker",
                        "VfRFWBCollideChecker", "V0RFWBCollideChecker",
                        "VlRFWBCollideChecker")):
        return "RFWBCollideChecker"
    if name.startswith("RealWBArbiter"):
        return "RealWBArbiter"
    if name.startswith("WBArbiter"):
        return "WBArbiter"
    if "SnapshotGenerator" in name:
        return "SnapshotGenerator"
    if name.startswith(("BusyTable", "VlBusyTable")):
        return "BusyTable"
    if name.startswith("FreeList"):
        return "FreeList"
    if name.startswith("MultiWakeupQueue"):
        return "MultiWakeupQueue"
    return "Unknown"


# =============================================================================
# Implementation
# =============================================================================
def _grant(valids: list[Value]) -> list[Value]:
    # ArbiterCtrl: first slot always granted, later slots need an empty prefix.
    # ArbiterCtrl：首槽恒授权，后续槽要求前缀全空。
    grants: list[Value] = []
    prefix: Value = Const(0, 1)
    for valid in valids:
        grants.append(valid & ~prefix)
        prefix = prefix | valid
    return grants


def _ptr_add(flag: Value, value: Value, increment: int, size: int) -> tuple[Value, Value]:
    # Advance a circular pointer by a constant with flag wrap. / 环形指针加常数并翻转旗标。
    if increment == 0:
        return value, flag
    total = value + increment
    wrapped = value + increment >= size
    return Mux(wrapped, total - size, total), Mux(wrapped, flag ^ 1, flag)


def _ptr_add_dyn(flag: Value, value: Value, increment: Value, size: int) -> tuple[Value, Value]:
    # Advance a circular pointer by a runtime amount with flag wrap. / 环形指针加运行期量并翻转旗标。
    total = value + increment
    wrapped = total >= size
    return Mux(wrapped, total - size, total), Mux(wrapped, flag ^ 1, flag)


def _popcount(bits: list[Value]) -> Value:
    # Runtime population count of one-bit terms. / 单位项的运行期计数。
    width = max(len(bits).bit_length(), 1)
    total: Value = Const(0, width)
    for bit in bits:
        total = total + bit
    return total


def _is_before(ptr: Value, ptr_flag: Value, other: Value, other_flag: Value,
               size: int) -> Value:
    # CircularQueuePtr.isBefore: strict ring order (wrap flips the comparison).
    # 环形队列指针严格先序判断（回绕翻转比较方向）。
    same_flag = ptr_flag == other_flag
    if size == 1:
        return (ptr == other) & same_flag
    return Mux(same_flag, ptr < other, ptr > other)


# Adapt Amaranth's runtime context DSL to its conservative static stubs. / 适配 Amaranth 运行期上下文 DSL 与保守静态存根。
def _if_context(module: Module, condition: Value) -> ContextManager[None]:
    return cast(ContextManager[None], module.If(condition))


# Adapt an Amaranth else-if context to the typed Build boundary. / 适配 Amaranth 否则如果上下文到类型化 Build 边界。
def _elif_context(module: Module, condition: Value) -> ContextManager[None]:
    return cast(ContextManager[None], module.Elif(condition))


# Adapt an Amaranth else context to the typed Build boundary. / 适配 Amaranth 否则上下文到类型化 Build 边界。
def _else_context(module: Module) -> ContextManager[None]:
    return cast(ContextManager[None], module.Else())


# Reduce a nonempty or empty value list with OR. / 对非空或空值列表执行或归约。
def _any_value(bits: Sequence[Value]) -> Value:
    result: Value = Const(0, 1)
    for bit in bits:
        result = result | bit
    return result


# Reduce a nonempty or empty value list with AND. / 对非空或空值列表执行与归约。
def _all_value(bits: Sequence[Value]) -> Value:
    result: Value = Const(1, 1)
    for bit in bits:
        result = result & bit
    return result


# Read a dynamically indexed Amaranth array as a Value. / 将动态索引的 Amaranth 数组读取为 Value。
def _array_value(values: Sequence[Value], index: Value) -> Value:
    return cast(Value, Array(values)[index])


class PortedModule(Elaboratable):
    """Binds the exact locked port surface and elaborates family behavior.

    绑定精确锁定的端口面并展开家族行为。
    """

    def __init__(self, name: str) -> None:
        spec = _specs()[name]
        self.module_name = name
        self.family = family_of(name)
        self.params: dict[str, Any] = spec.get("params", {})
        self.signals: dict[str, Signal] = {}
        self.dirs: dict[str, str] = {}
        for row in spec["ports"]:
            pname, direction, width = str(row[0]), str(row[1]), parse_width(str(row[2]))
            sig = Signal(width, name=pname)
            self.signals[pname] = sig
            self.dirs[pname] = direction
        self.outs = [self.signals[p] for p in self.signals if self.dirs[p] == "output"]

    def _domain(self, m: Module) -> None:
        # Bind locked clock/reset; modules without reset keep a reset-less FF set
        # except where the Scala source declares RegInit members explicitly.
        # 绑定锁定 clock/reset；无复位模块的触发器不接复位，Scala 显式 RegInit 成员除外。
        if "clock" not in self.signals:
            return
        cd = ClockDomain("sync", async_reset="reset" in self.signals)
        cd.clk = self.signals["clock"]
        if "reset" in self.signals:
            cd.rst = self.signals["reset"]
        m.domains += cd

    def elaborate(self, platform: Any) -> Module:
        m = Module()
        self._domain(m)
        getattr(self, "_elab_" + self.family)(m)
        return m

    # ------------------------------------------------------------------
    def _elab_RegFilePart(self, m: Module) -> None:
        # Register file part: per-index one-hot write, one-cycle read latency,
        # zero/initialised entry zero, combinational debug view.
        # 寄存器堆分片：逐下标一热写、一拍读延迟、零号表项置零/初始化、组合调试视图。
        p = self.params
        num_pregs = int(p["numPregs"])
        addr_width = int(p["addrWidth"])
        data_width = int(p["dataWidth"])
        has_zero = bool(p.get("hasZero"))
        vl_init = bool(p.get("vlInit"))

        mem_0 = Signal(data_width, name="mem_0", init=0, reset_less=not vl_init)
        mem: list[Value] = [mem_0]
        for index in range(1, num_pregs):
            mem.append(Signal(data_width, name=f"mem_{index}", reset_less=True))

        wport_ids = sorted({int(k[len("io_writePorts_"):].split("_")[0])
                            for k in self.signals if k.startswith("io_writePorts_")})
        rport_ids = sorted({int(k[len("io_readPorts_"):].split("_")[0])
                            for k in self.signals if k.startswith("io_readPorts_")})
        dport_ids = sorted({int(k[len("io_debug_rports_"):].split("_")[0])
                            for k in self.signals if k.startswith("io_debug_rports_")})

        lookup = Array([mem[i] if i < num_pregs else Const(0, data_width)
                        for i in range(1 << addr_width)])

        for index in range(num_pregs):
            if has_zero and index == 0:
                m.d.sync += mem_0.eq(Const(0, data_width))
                continue
            target = mem_0 if index == 0 else mem[index]
            hit: Value = Const(0, 1)
            data: Value = Const(0, data_width)
            for windex in wport_ids:
                wen = self.signals[f"io_writePorts_{windex}_wen"]
                waddr = self.signals[f"io_writePorts_{windex}_addr"]
                wdata = self.signals[f"io_writePorts_{windex}_data"]
                mine = wen & (waddr == index)
                data = Mux(mine, wdata, data)
                hit = hit | mine
            with _if_context(m, hit):
                m.d.sync += target.eq(data)

        for rindex in rport_ids:
            addr = self.signals[f"io_readPorts_{rindex}_addr"]
            data = self.signals[f"io_readPorts_{rindex}_data"]
            addr_reg = Signal(addr_width, name=f"rfaddr_{rindex}", reset_less=True)
            m.d.sync += addr_reg.eq(addr)
            m.d.comb += data.eq(lookup[addr_reg])

        for dindex in dport_ids:
            addr = self.signals[f"io_debug_rports_{dindex}_addr"]
            data = self.signals[f"io_debug_rports_{dindex}_data"]
            m.d.comb += data.eq(lookup[addr])

        for k in self.signals:
            if k.startswith("io_debug_all_rdata_"):
                index = int(k[len("io_debug_all_rdata_"):])
                m.d.comb += self.signals[k].eq(mem[index] if index < num_pregs
                                               else Const(0, data_width))

    # ------------------------------------------------------------------
    def _arbiter_core(self, m: Module, keys: list[str], counters: bool,
                      out_valid_sig: Signal | None,
                      out_bits_map: dict[str, Value]) -> None:
        # Inline WBArbiter/RealWBArbiter core over explicit channel keys.
        # 对显式通道键内联 WBArbiter/RealWBArbiter 核心。
        n = len(keys)
        if n == 0:
            return
        valids = [self.signals[f"io_in_{key}_valid"] for key in keys]
        out_ready: Value = self.signals.get("io_out_ready", Const(1, 1))
        final_valid: list[Value] = list(valids)
        if counters:
            width = 3
            threshold = Const(7, width)
            counters_sig = [Signal(width, name=f"cc_{keys[i]}") for i in range(n)]
            full = [Signal(name=f"cf_{keys[i]}") for i in range(n)]
            grants_probe = _grant(valids)
            for i in range(n):
                accepted = valids[i] & (
                    (grants_probe[i] & valids[i] | ~valids[i]) & out_ready)
                with _if_context(m, valids[i] & ~accepted):
                    with _if_context(m, counters_sig[i] == threshold):
                        m.d.sync += counters_sig[i].eq(threshold)
                    with _else_context(m):
                        m.d.sync += counters_sig[i].eq(counters_sig[i] + 1)
                    m.d.sync += full[i].eq(_all_value(
                        [counters_sig[i][bit] for bit in range(1, width)]))
                with _elif_context(m, valids[i] & accepted):
                    m.d.sync += counters_sig[i].eq(Const(0, width))
                    m.d.sync += full[i].eq(Const(0, 1))
            has_full = _any_value(full)
            has_full_req = _any_value([valids[i] & full[i] for i in range(n)])
            final_valid = [valids[i] & (~has_full | ~has_full_req | full[i])
                           for i in range(n)]
        grants = _grant(final_valid)
        chosen = Signal(max(n, 1), name="chosen")
        m.d.comb += chosen.eq(n - 1)
        for i in range(n - 1, -1, -1):
            with _if_context(m, final_valid[i]):
                m.d.comb += chosen.eq(i)
        for suffix, wires in out_bits_map.items():
            if n == 1:
                m.d.comb += wires.eq(self.signals[f"io_in_{keys[0]}_bits{suffix}"])
            else:
                ins = [self.signals[f"io_in_{key}_bits{suffix}"] for key in keys]
                m.d.comb += wires.eq(Array(ins)[chosen])
        for i, key in enumerate(keys):
            ready = self.signals.get(f"io_in_{key}_ready")
            if ready is not None:
                base = grants[i] & final_valid[i] if counters else grants[i]
                m.d.comb += ready.eq((base | ~valids[i]) & out_ready)
        if out_valid_sig is not None:
            last_grant = grants[-1] if grants else Const(0, 1)
            last_valid = final_valid[-1] if final_valid else Const(0, 1)
            m.d.comb += out_valid_sig.eq((~last_grant) | last_valid)

    def _out_bits_map(self, keys: list[str]) -> dict[str, Value]:
        # Collect out-bit fields shared with the given input channels. / 收集与输入通道共享的输出位域。
        result: dict[str, Value] = {}
        base = f"io_in_{keys[0]}_bits" if keys else ""
        candidates = [""] if keys and base in self.signals else []
        candidates += ["_" + k[len(base) + 1:] for k in sorted(self.signals)
                       if base and k.startswith(base + "_")]
        for suffix in candidates:
            out_name = "io_out_bits" + suffix
            if out_name in self.signals:
                result[suffix] = self.signals[out_name]
        return result

    def _elab_WBArbiter(self, m: Module) -> None:
        # Starvation-counter arbiter (WBArbiter.scala). / 带饥饿计数器的仲裁器。
        keys = self._flat_keys()
        self._arbiter_core(m, keys, counters=True,
                           out_valid_sig=self.signals.get("io_out_valid"),
                           out_bits_map=self._out_bits_map(keys))

    def _elab_RealWBArbiter(self, m: Module) -> None:
        # Plain first-valid write-back mux. / 纯首有效写回选择。
        keys = self._flat_keys()
        self._arbiter_core(m, keys, counters=False,
                           out_valid_sig=self.signals.get("io_out_valid"),
                           out_bits_map=self._out_bits_map(keys))

    def _flat_keys(self) -> list[str]:
        # Input channel keys in locked numeric order. / 按锁定数字顺序的输入通道键。
        keys = [k[len("io_in_"):-len("_valid")] for k in self.signals
                if k.startswith("io_in_") and k.endswith("_valid")]
        keys.sort(key=lambda k: [int(x) for x in k.split("_")])
        return keys

    def _elab_RFReadArbiter(self, m: Module) -> None:
        self._elab_grouped(m)

    def _elab_RFWBCollideChecker(self, m: Module) -> None:
        self._elab_grouped(m)

    def _elab_grouped(self, m: Module) -> None:
        # One WBArbiter core per physical-register port group; ungrouped
        # requests are ready-tied exactly as the pinned groups show.
        # 每个物理寄存器口组一个 WBArbiter 核心；未分组请求按钉死分组拉高 ready。
        groups = self.params.get("groups") or []
        covered: set[str] = set()
        driven_outs: set[str] = set()
        for gindex, group in enumerate(groups):
            keys = [str(item)[len("io_in_"):] if str(item).startswith("io_in_")
                    else str(item) for item in group["inputs"]]
            keys = [key[:-len("_valid")] if key.endswith("_valid") else key
                    for key in keys]
            covered.update(keys)
            out_valid = self.signals.get(f"io_out_{gindex}_valid")
            if out_valid is not None:
                driven_outs.add(f"io_out_{gindex}_valid")
            out_map: dict[str, Value] = {}
            for name in self.signals:
                if name.startswith(f"io_out_{gindex}_bits"):
                    suffix = name[len(f"io_out_{gindex}_bits"):]
                    out_map[suffix] = self.signals[name]
                    driven_outs.add(name)
            self._arbiter_core(m, keys, counters=True,
                               out_valid_sig=out_valid, out_bits_map=out_map)
        # Default-drive any locked output group the pinned grouping leaves
        # uncovered, so direction inference keeps them as outputs.
        # 默认驱动钉死分组未覆盖的输出组，保证方向推断仍为输出。
        for name in sorted(self.signals):
            if not name.startswith("io_out_") or name in driven_outs:
                continue
            if self.dirs.get(name) == "output":
                m.d.comb += self.signals[name].eq(Const(0, self.signals[name].width))
        for key in self._flat_keys():
            if key in covered:
                continue
            ready = self.signals.get(f"io_in_{key}_ready")
            if ready is not None:
                m.d.comb += ready.eq(Const(1, 1))

    # ------------------------------------------------------------------
    def _elab_SnapshotGenerator(self, m: Module) -> None:
        # Circular snapshot buffer with per-slot flush and enqueue recovery.
        # 环形快照缓冲：逐槽冲刷与入队指针恢复。
        p = self.params
        fields = [(str(f[0]), int(f[1])) for f in p["fields"]]
        num = int(p["numSnapshots"])
        ptr_w = max((num - 1).bit_length(), 1)
        enq_flag = Signal(name="snpt_enq_flag", init=0)
        enq_ptr = Signal(ptr_w, name="snpt_enq_ptr", init=0)
        deq_flag = Signal(name="snpt_deq_flag", init=0)
        deq_ptr = Signal(ptr_w, name="snpt_deq_ptr", init=0)
        valids = [Signal(name=f"snpt_valid_{i}", init=0) for i in range(num)]
        snaps: list[dict[str, Signal]] = []
        for i in range(num):
            snaps.append({fname: Signal(fwidth, name=f"snapt_{i}_{fname}",
                                        reset_less=True)
                          for fname, fwidth in fields})
        field_arrays = {fname: Array([snaps[i][fname] for i in range(num)])
                        for fname, _fwidth in fields}
        valids_array = Array(valids)

        enq = self.signals.get("io_enq", Const(0, 1))
        deq = self.signals.get("io_deq", Const(0, 1))
        redirect = self.signals.get("io_redirect", Const(0, 1))
        flush_vec = [self.signals[f"io_flushVec_{i}"] for i in range(num)
                     if f"io_flushVec_{i}" in self.signals]
        full = (enq_flag != deq_flag) & (enq_ptr == deq_ptr)

        with _if_context(m, ~redirect & ~full & enq):
            for fname, _fwidth in fields:
                src = self.signals.get(f"io_enqData_{fname}")
                if src is not None:
                    m.d.sync += field_arrays[fname][enq_ptr].eq(src)
            m.d.sync += valids_array[enq_ptr].eq(Const(1, 1))
            new_v, new_f = _ptr_add(enq_flag, enq_ptr, 1, num)
            m.d.sync += enq_ptr.eq(new_v)
            m.d.sync += enq_flag.eq(new_f)
        with _if_context(m, ~redirect & deq):
            m.d.sync += valids_array[deq_ptr].eq(Const(0, 1))
            new_v, new_f = _ptr_add(deq_flag, deq_ptr, 1, num)
            m.d.sync += deq_ptr.eq(new_v)
            m.d.sync += deq_flag.eq(new_f)
        for i in range(num):
            if i < len(flush_vec):
                with _if_context(m, flush_vec[i]):
                    m.d.sync += valids[i].eq(Const(0, 1))

        # Flush recovery: reposition the enqueue pointer past flushed snapshots.
        # 冲刷恢复：把入队指针移到被冲刷快照之后。
        if flush_vec:
            any_flush = _any_value([flush_vec[i] & valids[i] for i in range(num)])
            with _if_context(m, any_flush):
                candidates = [_ptr_add(deq_flag, deq_ptr, i, num) for i in range(num)]
                for i in range(num - 1):
                    if i == 0:
                        ok = (~_array_value(valids, deq_ptr)
                              | _array_value(flush_vec, deq_ptr))
                    else:
                        prev_v, _pf = candidates[i - 1]
                        this_v, _tf = candidates[i]
                        ok = (_array_value(valids, prev_v)
                              & (~_array_value(valids, this_v)
                                 | _array_value(flush_vec, this_v)))
                    with _if_context(m, ok):
                        m.d.sync += enq_ptr.eq(candidates[i][0])
                        m.d.sync += enq_flag.eq(candidates[i][1])
        for i in range(num):
            for fname, fwidth in fields:
                out = self.signals.get(f"io_snapshots_{i}_{fname}")
                if out is not None:
                    m.d.comb += out.eq(snaps[i][fname])
        if p.get("hasPtrs"):
            if "io_enqPtr_flag" in self.signals:
                m.d.comb += self.signals["io_enqPtr_flag"].eq(enq_flag)
                m.d.comb += self.signals["io_enqPtr_value"].eq(enq_ptr)
                m.d.comb += self.signals["io_deqPtr_flag"].eq(deq_flag)
                m.d.comb += self.signals["io_deqPtr_value"].eq(deq_ptr)
        if p.get("hasValids"):
            for i in range(num):
                out = self.signals.get(f"io_valids_{i}")
                if out is not None:
                    m.d.comb += out.eq(valids[i])

    # ------------------------------------------------------------------
    def _elab_BusyTable(self, m: Module) -> None:
        # Physical-register busy array: allocation/load-cancel set, write-back
        # and fast-wakeup clear, og0Cancel and load-cancel filtered wakeups,
        # plus the vl nonzero/vlmax side tables.
        # 物理寄存器忙位阵列：分配/load 取消置忙，写回与快速唤醒清忙，唤醒过滤
        # og0Cancel 与 load 取消，另含 vl 的 nonzero/vlmax 边表。
        p = self.params
        table_size = int(p["numPregs"])
        is_vl = p.get("vlWbInt") is not None

        alloc_ids = sorted({int(k[len("io_allocPregs_"):].split("_")[0])
                            for k in self.signals if k.startswith("io_allocPregs_")})
        wb_ids = sorted({int(k[len("io_wbPregs_"):].split("_")[0])
                         for k in self.signals if k.startswith("io_wbPregs_")})
        read_ids = sorted({int(k[len("io_read_"):].split("_")[0])
                           for k in self.signals if k.startswith("io_read_")})
        wakeups = p.get("wakeups") or []
        og_bits = [int(x) for x in (p.get("og0CancelBits") or [])]
        ld_slots = int(p.get("ldCancelCount") or 0)

        table = [Signal(name=f"table_r_{i}" if i else "table_r", init=0)
                 for i in range(table_size)]

        def req_mask(ids: list[int], prefix: str) -> list[Value]:
            masks: list[Value] = [Const(0, 1) for _ in range(table_size)]
            for index in ids:
                valid = self.signals[f"{prefix}_{index}_valid"]
                bits = self.signals[f"{prefix}_{index}_bits"]
                for entry in range(table_size):
                    masks[entry] = masks[entry] | Mux(valid, bits == entry, Const(0, 1))
            return masks

        wb_mask = req_mask(wb_ids, "io_wbPregs")
        alloc_mask = req_mask(alloc_ids, "io_allocPregs")

        vl_int = int(p["vlWbInt"]) if is_vl else -1
        vl_vf = int(p["vlWbVf"]) if is_vl else -1
        other_wb: list[Value] = [Const(0, 1) for _ in range(table_size)]
        if is_vl:
            for index in wb_ids:
                if index in (vl_int, vl_vf):
                    continue
                valid = self.signals[f"io_wbPregs_{index}_valid"]
                bits = self.signals[f"io_wbPregs_{index}_bits"]
                for entry in range(table_size):
                    other_wb[entry] = other_wb[entry] | Mux(valid, bits == entry,
                                                            Const(0, 1))

        # Load-dependency registers and cancel mask, per Scala semantics.
        # 依 Scala 语义的 load 依赖寄存器与取消掩码。
        dep_regs: list[list[Signal]] = []
        if ld_slots:
            for entry in range(table_size):
                row = [Signal(2, name=f"ld_{entry}_{slot}", init=0)
                       for slot in range(ld_slots)]
                dep_regs.append(row)
        cancel_mask: list[Value] = [Const(0, 1) for _ in range(table_size)]
        for entry in range(table_size):
            term: Value = Const(0, 1)
            for slot in range(ld_slots):
                for field, bit_index in (("ld1Cancel", 0), ("ld2Cancel", 1)):
                    port_name = f"io_ldCancel_{slot}_{field}"
                    if port_name in self.signals:
                        term = term | (self.signals[port_name]
                                       & dep_regs[entry][slot][bit_index])
            cancel_mask[entry] = term

        # Wakeup one-hot and per-preg mask with og0Cancel/is0Lat filtering.
        # 唤醒一热与逐寄存器掩码（过滤 og0Cancel 与 is0Lat）。
        wakeup_masks: list[Value] = []
        for entry in range(table_size):
            one_hot: list[Value] = []
            terms: list[Value] = []
            for wakeup in wakeups:
                group = str(wakeup["group"])
                windex = int(wakeup["index"])
                valid = self.signals[f"io_wakeUp{group}_{windex}_valid"]
                wen = self.signals[f"io_wakeUp{group}_{windex}_bits_{wakeup['wenField']}"]
                pdest = self.signals[f"io_wakeUp{group}_{windex}_bits_pdest"]
                term = valid & wen & (pdest == entry)
                if bool(wakeup.get("is0Lat")) and og_bits:
                    cancel = Const(0, 1)
                    for bit in og_bits:
                        cancel = cancel | self.signals[f"io_og0Cancel_{bit}"]
                    term = term & ~cancel
                if bool(wakeup.get("hasDep")) and ld_slots:
                    for slot in range(ld_slots):
                        dep = self.signals[
                            f"io_wakeUp{group}_{windex}_bits_loadDependency_{slot}"]
                        for field, bit_index in (("ld1Cancel", 0), ("ld2Cancel", 1)):
                            port_name = f"io_ldCancel_{slot}_{field}"
                            if port_name in self.signals:
                                term = term & ~(self.signals[port_name]
                                                & dep[bit_index])
                terms.append(term)
                one_hot.append(term)
            wakeup_masks.append(_any_value(terms))
            if dep_regs and terms:
                shift: list[Value] = []
                for slot in range(ld_slots):
                    shifted: Value = Const(0, 2)
                    for wpos, wakeup in enumerate(wakeups):
                        group = str(wakeup["group"])
                        windex = int(wakeup["index"])
                        if bool(wakeup.get("hasDep")):
                            dep = self.signals[
                                f"io_wakeUp{group}_{windex}_bits_loadDependency_{slot}"]
                            candidate = Mux(dep[1], Const(2, 2),
                                            Mux(dep[0], Const(1, 2), Const(0, 2)))
                            # dep << 1 keeps bit0 clear; captured above.
                            candidate = dep << 1
                        else:
                            candidate = Const(2 if slot == windex else 0, 2)
                        shifted = Mux(one_hot[wpos], candidate, shifted)
                    shift.append(shifted)
                for slot in range(ld_slots):
                    hold = _any_value([dep_regs[entry][slot][0],
                                       dep_regs[entry][slot][1]])
                    with _if_context(m, wakeup_masks[entry]):
                        m.d.sync += dep_regs[entry][slot].eq(shift[slot])
                    with _elif_context(m, hold):
                        m.d.sync += dep_regs[entry][slot].eq(dep_regs[entry][slot] << 1)

        for entry in range(table_size):
            wake = wakeup_masks[entry] | wb_mask[entry]
            busy = alloc_mask[entry] | cancel_mask[entry]
            update: Value = Mux(wake, Const(0, 1),
                                Mux(busy, Const(1, 1), table[entry]))
            enable = wake | busy
            if is_vl:
                int_hit = self.signals[f"io_wbPregs_{vl_int}_valid"] & (
                    self.signals[f"io_wbPregs_{vl_int}_bits"] == entry)
                vf_hit = self.signals[f"io_wbPregs_{vl_vf}_valid"] & (
                    self.signals[f"io_wbPregs_{vl_vf}_bits"] == entry)
                enable = enable | int_hit | vf_hit | other_wb[entry]
            with _if_context(m, enable):
                m.d.sync += table[entry].eq(update)

        for rindex in read_ids:
            req = self.signals[f"io_read_{rindex}_req"]
            resp = self.signals[f"io_read_{rindex}_resp"]
            bypass = Const(0, 1)
            for aindex in alloc_ids:
                bypass = bypass | (self.signals[f"io_allocPregs_{aindex}_valid"]
                                   & (self.signals[f"io_allocPregs_{aindex}_bits"] == req))
            m.d.comb += resp.eq(~(_array_value(table, req) | bypass))
            for slot in range(ld_slots):
                out_name = f"io_read_{rindex}_loadDependency_{slot}"
                if out_name in self.signals:
                    m.d.comb += self.signals[out_name].eq(Array(dep_regs)[req][slot])

        if is_vl:
            zero_int = self.signals["io_vl_Wb_vlWriteBackInfo_vlFromIntIsZero"]
            zero_vf = self.signals["io_vl_Wb_vlWriteBackInfo_vlFromVfIsZero"]
            max_int = self.signals["io_vl_Wb_vlWriteBackInfo_vlFromIntIsVlmax"]
            max_vf = self.signals["io_vl_Wb_vlWriteBackInfo_vlFromVfIsVlmax"]
            for name_prefix, is_max in (("nonzero_table_r", False),
                                        ("vlmax_table_r", True)):
                regs = [Signal(name=f"{name_prefix}_{e}" if e else name_prefix, init=0)
                        for e in range(table_size)]
                for entry in range(table_size):
                    int_hit = self.signals[f"io_wbPregs_{vl_int}_valid"] & (
                        self.signals[f"io_wbPregs_{vl_int}_bits"] == entry)
                    vf_hit = self.signals[f"io_wbPregs_{vl_vf}_valid"] & (
                        self.signals[f"io_wbPregs_{vl_vf}_bits"] == entry)
                    if is_max:
                        update = Mux(int_hit, ~max_int,
                                     Mux(vf_hit, ~max_vf,
                                         Mux(other_wb[entry] | alloc_mask[entry]
                                             | cancel_mask[entry],
                                             Const(1, 1), regs[entry])))
                    else:
                        update = Mux(int_hit, zero_int,
                                     Mux(vf_hit, zero_vf,
                                         Mux(other_wb[entry] | alloc_mask[entry]
                                             | cancel_mask[entry],
                                             Const(1, 1), regs[entry])))
                    enable = (int_hit | vf_hit | other_wb[entry]
                              | alloc_mask[entry] | cancel_mask[entry])
                    with _if_context(m, enable):
                        m.d.sync += regs[entry].eq(update)
                for rindex in read_ids:
                    req = self.signals[f"io_read_{rindex}_req"]
                    out = self.signals[f"io_vl_read_vlReadInfo_{rindex}_"
                                       + ("is_vlmax" if is_max else "is_nonzero")]
                    m.d.comb += out.eq(~_array_value(regs, req))

    # ------------------------------------------------------------------
    def _elab_FuBusyTableWrite(self, m: Module) -> None:
        # Per-FU-latency busy vector: dequeue sets latency-1, og0/og1 failures
        # clear latency-2/3 for matching FU types after the right-shift aging.
        # 逐 FU 延迟忙向量：deq 置 lat-1，og0/og1 失败按匹配 fuType 清 lat-2/3，
        # 且每拍右移老化。
        p = self.params
        table_size = int(p["tableSize"])
        masks = p["masks"]
        lat_fus: dict[int, set[int]] = {}
        for source, offset in (("deq", 1), ("og0", 2), ("og1", 3)):
            for bit, fus in (masks.get(source) or {}).items():
                lat_fus.setdefault(int(bit) + offset, set()).update(int(x) for x in fus)
        table = Signal(table_size, name="fuBusyTable", init=0)
        fu_type = self.signals.get("io_in_deqResp_bits_fuType")
        deq_valid = self.signals.get("io_in_deqResp_valid", Const(0, 1))
        og0_valid = self.signals.get("io_in_og0Resp_valid", Const(0, 1))
        og1_valid = self.signals.get("io_in_og1Resp_valid", Const(0, 1))
        og1_resp = self.signals.get("io_in_og1Resp_bits_resp", Const(0, 2))

        def match_vec(offset: int) -> Value:
            bits: list[Value] = []
            for lat in range(table_size):
                term = Const(0, 1)
                if fu_type is not None:
                    for fu in sorted(lat_fus.get(lat + offset, ())):
                        term = term | fu_type[fu]
                bits.append(term)
            return Cat(*bits)
        deq_set = Mux(deq_valid, match_vec(0) >> 1, Const(0, table_size))
        og0_clear = Mux(og0_valid, match_vec(0) >> 2, Const(0, table_size))
        og1_clear = Mux(og1_valid & (og1_resp == 0), match_vec(0) >> 3,
                        Const(0, table_size))
        m.d.sync += table.eq((table >> 1) & ~og0_clear & ~og1_clear | deq_set)
        m.d.comb += self.signals["io_out_fuBusyTable"].eq(table)
        if "io_out_deqRespSet" in self.signals:
            m.d.comb += self.signals["io_out_deqRespSet"].eq(
                Mux(deq_valid, match_vec(0), Const(0, table_size)))

    # ------------------------------------------------------------------
    def _elab_WbFuBusyTable(self, m: Module) -> None:
        # Pure combinational closure: evaluate the pinned OR/concat/slice ASTs.
        # 纯组合闭包：求值钉死的 OR/拼接/位选 AST。
        params = self.params
        wires: dict[str, Value] = {}

        def evaluate(node: list[Any]) -> Value:
            kind = node[0]
            if kind == "IN":
                name = str(node[1])
                if name in self.signals:
                    return self.signals[name]
                return wires[name]
            if kind == "SL":
                sig = self.signals[str(node[1])] if str(node[1]) in self.signals \
                    else wires[str(node[1])]
                return sig[int(node[3]):int(node[2]) + 1]
            if kind == "C":
                return Const(int(node[1]), int(node[2]))
            if kind == "CC":
                return Cat(*[evaluate(item) for item in node[1]])
            if kind == "OR":
                acc: Value = evaluate(node[1][0])
                for item in node[1][1:]:
                    acc = acc | evaluate(item)
                return acc
            raise ValueError(kind)

        for name in sorted(params.get("wires") or {}):
            entry = params["wires"][name]
            wires[name] = evaluate(entry["expr"])
        for name in sorted(params.get("assign") or {}):
            entry = params["assign"][name]
            expr = evaluate(entry["expr"])
            target = self.signals[name]
            m.d.comb += target.eq(expr)

    # ------------------------------------------------------------------
    def _elab_DifftestRat(self, m: Module) -> None:
        # Difftest capture leaf: registers sampled by enable for the DPI sink.
        # Difftest 采集叶子：由 enable 采样的寄存器供 DPI 使用。
        p = self.params
        num_values = int(p["numValues"])
        regs = [Signal(int(p["valueWidth"]), name=f"rat_{i}", init=0, reset_less=True)
                for i in range(num_values)]
        enable = self.signals.get("enable", Const(0, 1))
        with _if_context(m, enable):
            for i in range(num_values):
                m.d.sync += regs[i].eq(self.signals[f"io_value_{i}"])

    # ------------------------------------------------------------------
    def _elab_FreeList(self, m: Module) -> None:
        # Ring-buffer free list: one-hot free-mask selection, gated free request
        # registers, head/tail pointers with flags, allocateReq absent => zero.
        # 环形空闲表：一热空闲掩码选择、门控空闲请求寄存器、带旗标头尾指针；
        # 无 allocateReq 口 => 恒零。
        p = self.params
        size = int(p["size"])
        alloc_width = int(p["allocWidth"])
        free_width = int(p["freeWidth"])
        ptr_w = max((size - 1).bit_length(), 1)
        addr_w = max(ptr_w, 1)

        head_flag = Signal(name="head_flag", init=0)
        head_ptr = Signal(ptr_w, name="head_ptr", init=0)
        tail_flag = Signal(name="tail_flag", init=1)
        tail_ptr = Signal(ptr_w, name="tail_ptr", init=0)
        free_list = [Signal(addr_w, name=f"freeList_{i}", init=i, reset_less=True)
                     for i in range(size)]
        free_mask = Signal(size, name="freeMask", init=0)
        free_slot_cnt = Signal((size).bit_length(), name="freeSlotCnt", init=size)

        free = self.signals.get("io_free")
        do_alloc = [self.signals[f"io_doAllocate_{i}"]
                    for i in range(alloc_width) if f"io_doAllocate_{i}" in self.signals]

        # Combinational free-slot selection per free port (priority encoded).
        # 每空闲口的组合空闲槽选择（优先编码）。
        free_sel: list[Value] = [Const(0, size) for _ in range(free_width)]
        free_req: list[Value] = []
        free_oh: list[Value] = []
        rem = free_mask
        for fport in range(free_width):
            rem_bits = Cat(*[rem[i * free_width + fport] for i in range(size // free_width)])
            free_req.append(_any_value(
                [rem_bits[index] for index in range(size // free_width)]))
            one_hot = Const(0, size)
            taken: Value = Const(0, 1)
            for i in range(size // free_width):
                hit = rem_bits[i] & ~taken
                one_hot = one_hot | Mux(hit, Const(1 << (i * free_width + fport), size),
                                        Const(0, size))
                taken = taken | rem_bits[i]
            free_oh.append(one_hot)
        for fport in range(free_width):
            gated_req = Signal(name=f"freeReq_{fport}", init=0)
            with _if_context(m, free_req[fport]):
                m.d.sync += gated_req.eq(Const(1, 1))
            gated_oh = Signal(size, name=f"freeSlotOH_{fport}", init=0)
            with _if_context(m, free_req[fport]):
                m.d.sync += gated_oh.eq(free_oh[fport])
            free_req[fport] = gated_req
            free_oh[fport] = gated_oh
            free_sel[fport] = Mux(gated_req, gated_oh, Const(0, size))

        if free is not None:
            sel_all = free_sel[0]
            for item in free_sel[1:]:
                sel_all = sel_all | item
            m.d.sync += free_mask.eq((free | free_mask) & ~sel_all)
            offset = 0
            for fport in range(free_width):
                enq_v, _enq_f = _ptr_add(tail_flag, tail_ptr, offset, size)
                with _if_context(m, free_req[fport]):
                    m.d.sync += _array_value(free_list, enq_v).eq(
                        self._oh_to_uint(free_oh[fport], addr_w))
                offset += 1
            do_free = _any_value(free_req)
            tv, tf = _ptr_add_dyn(tail_flag, tail_ptr, _popcount(list(free_req)), size)
            with _if_context(m, do_free):
                m.d.sync += tail_ptr.eq(tv)
                m.d.sync += tail_flag.eq(tf)

        # Allocation: allocateReq is disconnected in every locked instance, so
        # offsets are zero and every port previews the head slot.
        # 分配：所有锁定实例均无 allocateReq，偏移恒零，各口均预览头槽。
        for i in range(alloc_width):
            if f"io_canAllocate_{i}" in self.signals:
                m.d.comb += self.signals[f"io_canAllocate_{i}"].eq(
                    _is_before(head_ptr, head_flag, tail_ptr, tail_flag, size))
            if f"io_allocateSlot_{i}" in self.signals:
                m.d.comb += self.signals[f"io_allocateSlot_{i}"].eq(
                    _array_value(free_list, head_ptr))
        if do_alloc:
            num_alloc = _popcount(do_alloc)
            hv, hf = _ptr_add_dyn(head_flag, head_ptr, num_alloc, size)
            with _if_context(m, _any_value(do_alloc)):
                m.d.sync += head_ptr.eq(hv)
                m.d.sync += head_flag.eq(hf)
        # Free-slot counter follows tail/head pointers every cycle.
        # 空闲槽计数每拍跟随头尾指针。
        distance = self._distance(tail_ptr, tail_flag, head_ptr, head_flag, size)
        m.d.sync += free_slot_cnt.eq(distance)
        if "io_empty" in self.signals:
            m.d.comb += self.signals["io_empty"].eq(free_slot_cnt == 0)
        if "io_validCount" in self.signals:
            m.d.comb += self.signals["io_validCount"].eq(
                Const(size, self.signals["io_validCount"].width) - free_slot_cnt)

    @staticmethod
    def _oh_to_uint(one_hot: Value, width: int) -> Value:
        # One-hot to binary conversion. / 一热转二进制。
        result: Value = Const(0, width)
        for i in range(one_hot.shape().width):
            result = Mux(one_hot[i], Const(i, width), result)
        return result

    @staticmethod
    def _distance(tail: Value, tail_flag: Value, head: Value, head_flag: Value,
                  size: int) -> Value:
        # CircularQueuePtr.distanceBetween: free slots between tail and head.
        # 环形指针距离：尾与头之间的空闲槽位。
        raw = tail - head
        return Mux(tail_flag == head_flag, raw, raw + size)

    # ------------------------------------------------------------------
    def _elab_MultiWakeupQueue(self, m: Module) -> None:
        # Replicated flushable wake-up pipes of different latencies followed by
        # the registered lastConnect stage; flush filtering follows the stage
        # rules (stage>=2 uses redirect/load-cancel/og-fail).
        # 复制的不同延迟可冲刷唤醒管道，后接寄存的 lastConnect 段；冲刷过滤遵循
        # 阶段规则（阶段>=2 使用 redirect/load 取消/og 失败）。
        p = self.params
        pipes = [(int(item["lat"])) for item in (p.get("pipes") or [])]
        has_lat = "io_enq_bits_lat" in self.signals
        enq_valid = self.signals.get("io_enq_valid", Const(0, 1))
        redirect_v = self.signals.get("io_flush_redirect_valid")
        red_flag = self.signals.get("io_flush_redirect_bits_robIdx_flag")
        red_value = self.signals.get("io_flush_redirect_bits_robIdx_value")
        og0 = self.signals.get("io_flush_og0Fail")
        og1 = self.signals.get("io_flush_og1Fail")
        flush_slots = sorted({int(mo.group(1)) for mo in
                              (re.match(r"io_flush_ldCancel_(\d+)_", k) for k in self.signals)
                              if mo})
        flush_active = redirect_v is not None

        def flush_term(dep_bits: list[Value] | None, stage: int) -> Value:
            term: Value = Const(0, 1)
            if redirect_v is not None and red_flag is not None and red_value is not None:
                uop_flag = self.signals.get("io_enq_bits_uop_robIdx_flag")
                uop_value = self.signals.get("io_enq_bits_uop_robIdx_value")
                if uop_flag is not None and uop_value is not None:
                    term = term | (redirect_v & (uop_flag != red_flag)
                                   & (uop_value == red_value))
            if dep_bits and flush_slots:
                for slot in flush_slots:
                    cancel = self.signals.get(f"io_flush_ldCancel_{slot}_ld2Cancel")
                    if cancel is not None and dep_bits[slot].shape().width > 1:
                        term = term | (cancel & dep_bits[slot][1])
            if stage == 1 and og0 is not None:
                term = term | og0
            if stage == 2 and og1 is not None:
                term = term | og1
            return term

        deq_fields: list[tuple[str, int]] = [(str(f[0]), int(f[1]))
                                             for f in (p.get("deqFields") or [])
                                             if f"io_deq_bits_{f[0]}" in self.signals]
        enq_suffix_map: dict[str, str] = {}
        for fname, _w in deq_fields:
            base = fname
            source = None
            for cand in (f"uop_{base}", base):
                if f"io_enq_bits_{cand}" in self.signals:
                    source = cand
                    break
            ld = re.match(r"loadDependency(?:Copy)?_(\d+)(?:_(\d+))?$", base)
            if source is None and ld:
                slot = ld.group(2) or ld.group(1)
                source = f"uop_loadDependency_{slot}"
            elif source is None and base.startswith("pdestCopy_"):
                source = "uop_pdest"
            elif source is None and base.startswith("rfWenCopy_"):
                source = "uop_rfWen"
            enq_suffix_map[base] = source if source else "uop_" + base

        pipe_valids: list[Value] = []
        pipe_bits: list[dict[str, Value]] = []
        for lat in pipes:
            valids: list[Value] = [enq_valid]
            bits_now: dict[str, Value] = {}
            for fname, _w in deq_fields:
                src = enq_suffix_map.get(fname)
                src_sig = self.signals.get(f"io_enq_bits_{src}") if src else None
                bits_now[fname] = src_sig if src_sig is not None else Const(0, 1)
            for stage in range(lat):
                reg_v = Signal(name=f"pipe_valid_{lat}_{stage}", init=0)
                next_bits: dict[str, Value] = {}
                for fname, _w in deq_fields:
                    reg_b = Signal(self.signals[f"io_deq_bits_{fname}"].width,
                                   name=f"pipe_bits_{lat}_{stage}_{fname}",
                                   reset_less=True)
                    shifted = bits_now[fname]
                    if fname.startswith("loadDependency") and shifted.shape().width > 1:
                        shifted = shifted << 1
                    with _if_context(m, valids[stage]):
                        m.d.sync += reg_b.eq(shifted)
                    next_bits[fname] = reg_b
                stage_flush = Const(0, 1) if stage == 0 else flush_term(
                    [bits_now[f] for f, _w in deq_fields if f.startswith("loadDependency")],
                    stage + 1)
                m.d.sync += reg_v.eq(valids[stage] & ~stage_flush)
                valids.append(reg_v)
                bits_now = next_bits
            deq_valid = valids[-1]
            if lat > 0:
                deq_valid = deq_valid & ~flush_term(
                    [bits_now[f] for f, _w in deq_fields if f.startswith("loadDependency")],
                    lat)
            pipe_valids.append(deq_valid)
            pipe_bits.append(bits_now)

        any_valid = _any_value(pipe_valids)
        last_valid = Signal(name="lastConnect_valid", init=0)
        m.d.sync += last_valid.eq(any_valid)
        for fname, _w in deq_fields:
            out = self.signals[f"io_deq_bits_{fname}"]
            selected: Value = None  # type: ignore[assignment]
            for index, bits_map in enumerate(pipe_bits):
                if selected is None:
                    selected = Mux(pipe_valids[index], bits_map[fname], Const(0, out.width))
                else:
                    selected = Mux(pipe_valids[index], bits_map[fname], selected)
            if selected is None:
                selected = Const(0, out.width)
            reg_out = Signal(out.width, name=f"last_{fname}", reset_less=True)
            m.d.sync += reg_out.eq(selected)
            m.d.comb += out.eq(reg_out)
        if "io_deq_valid" in self.signals:
            m.d.comb += self.signals["io_deq_valid"].eq(last_valid)
        del flush_active

    # ------------------------------------------------------------------
    def _elab_RenameTable(self, m: Module) -> None:
        # Speculative rename table with arch table, inline snapshots, T1 write
        # pipeline, read bypass, old_pdest/need_free commit bookkeeping.
        # 投机重命名表：含架构表、内联快照、T1 写流水、读旁路与
        # old_pdest/need_free 提交簿记。
        p = self.params
        reg_count = int(p["regCount"])
        preg_width = int(p["pregWidth"])
        addr_w = max((reg_count - 1).bit_length(), 1)
        commit_width = int(p["commitWidth"])
        snap_count = int(p["numSnapshots"])
        is_int = self.module_name == "RenameTable"
        init_val = (lambda i: 0) if is_int else (lambda i: i)

        spec_table = [Signal(preg_width, name=f"spec_{i}", init=init_val(i))
                      for i in range(reg_count)]
        arch_table = [Signal(preg_width, name=f"arch_{i}", init=init_val(i))
                      for i in range(reg_count)]
        snapshots = [[Signal(preg_width, name=f"snpt_{s}_{i}", reset_less=True)
                      for i in range(reg_count)] for s in range(snap_count)]
        snap_cols = [Array([snapshots[s][i] for s in range(snap_count)])
                     for i in range(reg_count)]
        snpt_valids = [Signal(name=f"snpt_valid_{s}", init=0) for s in range(snap_count)]
        snpt_valids_array = Array(snpt_valids)
        ptr_w = max((snap_count - 1).bit_length(), 1)
        enq_flag = Signal(name="snpt_enq_flag", init=0)
        enq_ptr = Signal(ptr_w, name="snpt_enq_ptr", init=0)
        deq_flag = Signal(name="snpt_deq_flag", init=0)
        deq_ptr = Signal(ptr_w, name="snpt_deq_ptr", init=0)

        redirect = self.signals["io_redirect"]
        enq = self.signals["io_snpt_snptEnq"]
        deq = self.signals["io_snpt_snptDeq"]
        use_snpt = self.signals["io_snpt_useSnpt"]
        snpt_select = self.signals["io_snpt_snptSelect"]
        flush_vec = [self.signals[f"io_snpt_flushVec_{i}"] for i in range(snap_count)]

        t1_redirect = Signal(name="t1_redirect", init=0)
        m.d.sync += t1_redirect.eq(redirect)
        t2_redirect = Signal(name="t2_redirect", init=0)
        m.d.sync += t2_redirect.eq(t1_redirect)

        # Snapshot buffer update (T1). / 快照缓冲更新（T1）。
        full = (enq_flag != deq_flag) & (enq_ptr == deq_ptr)
        with _if_context(m, ~t1_redirect & ~full & enq):
            for i in range(reg_count):
                m.d.sync += snap_cols[i][enq_ptr].eq(spec_table[i])
            m.d.sync += snpt_valids_array[enq_ptr].eq(Const(1, 1))
            nv, nf = _ptr_add(enq_flag, enq_ptr, 1, snap_count)
            m.d.sync += enq_ptr.eq(nv)
            m.d.sync += enq_flag.eq(nf)
        with _if_context(m, ~t1_redirect & deq):
            m.d.sync += snpt_valids_array[deq_ptr].eq(Const(0, 1))
            nv, nf = _ptr_add(deq_flag, deq_ptr, 1, snap_count)
            m.d.sync += deq_ptr.eq(nv)
            m.d.sync += deq_flag.eq(nf)
        for s in range(snap_count):
            with _if_context(m, flush_vec[s]):
                m.d.sync += snpt_valids[s].eq(Const(0, 1))
        if flush_vec:
            any_flush = _any_value([flush_vec[i] & snpt_valids[i]
                                    for i in range(snap_count)])
            with _if_context(m, any_flush):
                candidates = [_ptr_add(deq_flag, deq_ptr, i, snap_count)
                              for i in range(snap_count)]
                for i in range(snap_count - 1):
                    if i == 0:
                        ok = (~_array_value(snpt_valids, deq_ptr)
                              | _array_value(flush_vec, deq_ptr))
                    else:
                        prev_v, _pf = candidates[i - 1]
                        this_v, _tf = candidates[i]
                        ok = (_array_value(snpt_valids, prev_v)
                              & (~_array_value(snpt_valids, this_v)
                                 | _array_value(flush_vec, this_v)))
                    with _if_context(m, ok):
                        m.d.sync += enq_ptr.eq(candidates[i][0])
                        m.d.sync += enq_flag.eq(candidates[i][1])

        # T1 spec writes. / T1 投机写。
        read_ids = sorted({int(k[len("io_readPorts_"):].split("_")[0])
                           for k in self.signals if k.startswith("io_readPorts_")})
        spec_ids = sorted({int(k[len("io_specWritePorts_"):].split("_")[0])
                           for k in self.signals if k.startswith("io_specWritePorts_")})
        t1_wen = [Signal(name=f"t1_wen_{i}", init=0) for i in spec_ids]
        t1_waddr = [Signal(addr_w, name=f"t1_waddr_{i}", init=0) for i in spec_ids]
        t1_wdata = [Signal(preg_width, name=f"t1_wdata_{i}", init=0) for i in spec_ids]
        for pos, i in enumerate(spec_ids):
            wen = self.signals[f"io_specWritePorts_{i}_wen"]
            # Fixed-address instances (no _addr port) write table entry i.
            # 无 _addr 端口的定址实例写表项 i。
            waddr = self.signals.get(f"io_specWritePorts_{i}_addr",
                                     Const(i, addr_w))
            wdata = self.signals[f"io_specWritePorts_{i}_data"]
            m.d.sync += t1_wen[pos].eq(Mux(redirect, Const(0, 1), wen))
            m.d.sync += t1_waddr[pos].eq(waddr)
            m.d.sync += t1_wdata[pos].eq(wdata)
        t2_redirect_r = Signal(name="t2_redirect_ff", init=0)
        m.d.sync += t2_redirect_r.eq(t1_redirect)

        for i in range(reg_count):
            match: Value = Const(0, 1)
            data: Value = Const(0, preg_width)
            for pos, _sid in enumerate(spec_ids):
                hit = t1_wen[pos] & (t1_waddr[pos] == i)
                data = Mux(hit, t1_wdata[pos], data)
                match = match | hit
            snpt_value = snap_cols[i][snpt_select]
            recovered = Mux(use_snpt, snpt_value, Array(arch_table)[i])
            m.d.sync += spec_table[i].eq(Mux(t2_redirect_r, recovered,
                                             Mux(match, data, spec_table[i])))

        # Arch writes and old_pdest/need_free. / 架构写与 old_pdest/need_free。
        arch_ids = sorted({int(k[len("io_archWritePorts_"):].split("_")[0])
                           for k in self.signals if k.startswith("io_archWritePorts_")})
        old_pdest = [Signal(preg_width, name=f"old_pdest_{i}", init=0) for i in range(commit_width)]
        need_free = [Signal(name=f"need_free_{i}", init=0) for i in range(commit_width)]
        for i in arch_ids:
            wen = self.signals[f"io_archWritePorts_{i}_wen"]
            waddr = self.signals.get(f"io_archWritePorts_{i}_addr",
                                     Const(i, addr_w))
            wdata = self.signals[f"io_archWritePorts_{i}_data"]
            m.d.sync += Array(arch_table)[waddr].eq(Mux(wen, wdata, Array(arch_table)[waddr]))
            older: Value = Mux(wen, Array(arch_table)[waddr], Const(0, preg_width))
            for j in range(i):
                if j in arch_ids:
                    jwen = self.signals[f"io_archWritePorts_{j}_wen"]
                    jaddr = self.signals.get(f"io_archWritePorts_{j}_addr",
                                             Const(j, addr_w))
                    jdata = self.signals[f"io_archWritePorts_{j}_data"]
                    older = Mux(jwen & (jaddr == waddr), jdata, older)
            m.d.sync += old_pdest[i].eq(older)
        for i in range(commit_width):
            if i < len(arch_ids):
                duplicate: Value = Const(0, 1)
                for j in range(i):
                    duplicate = duplicate | (old_pdest[j] == old_pdest[i])
                in_arch = Const(1, 1)
                for e in range(reg_count):
                    in_arch = in_arch & (Array(arch_table)[e] != old_pdest[i])
                m.d.sync += need_free[i].eq(in_arch & ~duplicate)
            if f"io_old_pdest_{i}" in self.signals:
                m.d.comb += self.signals[f"io_old_pdest_{i}"].eq(old_pdest[i])
            if f"io_need_free_{i}" in self.signals:
                m.d.comb += self.signals[f"io_need_free_{i}"].eq(need_free[i])

        # Read path: T1 address capture, T1 write bypass, redirect suppression.
        # 读路径：T1 地址捕获、T1 写旁路、redirect 抑制。
        for rindex in read_ids:
            hold = self.signals.get(f"io_readPorts_{rindex}_hold")
            addr = self.signals.get(f"io_readPorts_{rindex}_addr")
            data = self.signals[f"io_readPorts_{rindex}_data"]
            # Fixed-index readers (no _addr port) read table entry rindex.
            # 无 _addr 端口的定址读口读表项 rindex。
            t1_raddr: Value
            if addr is None:
                t1_raddr = Const(rindex, addr_w)
            else:
                t1_raddr = Signal(addr_w, name=f"t1_raddr_{rindex}", init=0)
                m.d.sync += t1_raddr.eq(Mux(hold, t1_raddr, addr))
            t0_bypass: list[Value] = []
            for pos, sid in enumerate(spec_ids):
                wen = self.signals[f"io_specWritePorts_{sid}_wen"]
                waddr = self.signals.get(f"io_specWritePorts_{sid}_addr",
                                         Const(sid, addr_w))
                compare = waddr if addr is None else Mux(hold, waddr == t1_raddr,
                                                         waddr == addr)
                t0_bypass.append(wen & compare)
            t1_bypass = [Signal(name=f"t1_bypass_{rindex}_{pos}", init=0)
                         for pos in range(len(t0_bypass))]
            for pos, bypass in enumerate(t1_bypass):
                m.d.sync += bypass.eq(Mux(redirect, Const(0, 1), t0_bypass[pos]))
            t1_bypass_data: Value = Const(0, preg_width)
            for pos, _sid in enumerate(spec_ids):
                t1_bypass_data = Mux(t1_bypass[pos], t1_wdata[pos], t1_bypass_data)
            m.d.comb += data.eq(Mux(_any_value(t1_bypass), t1_bypass_data,
                                    Array(spec_table)[t1_raddr]))

        # Difftest base output. / Difftest 基表输出。
        for i in range(int(p.get("numDiffRatBase") or 0)):
            m.d.comb += self.signals[f"io_diffRatBase_{i}"].eq(arch_table[i])

    # ------------------------------------------------------------------
    def _elab_RenameTableWrapper(self, m: Module) -> None:
        # Wiring of the int/fp/vec rename tables plus single-entry v0/vl maps,
        # commit/walk port mapping and per-family old_pdest/need_free.
        # int/fp/vec 重命名表布线加单表项 v0/vl 映射，提交/行走口映射与逐族
        # old_pdest/need_free。
        p = self.params
        commit_width = 6
        ldest_w = 6
        preg_width = 8
        fams = ("int", "fp", "vec")
        spec_tables: dict[str, list[Signal]] = {}
        arch_tables: dict[str, list[Signal]] = {}
        sizes = {"int": 32, "fp": 32, "vec": 32}
        for fam in fams:
            spec_tables[fam] = [Signal(preg_width, name=f"{fam}_spec_{i}", init=0)
                                for i in range(sizes[fam])]
            arch_tables[fam] = [Signal(preg_width, name=f"{fam}_arch_{i}", init=0)
                                for i in range(sizes[fam])]
        addr_w = 5
        t1_wen: dict[str, Signal] = {}
        t1_waddr: dict[str, Signal] = {}
        t1_wdata: dict[str, Signal] = {}
        redirect = self.signals["io_redirect"]
        t1_redirect = Signal(name="t1_redirect", init=0)
        t2_redirect = Signal(name="t2_redirect", init=0)
        m.d.sync += t1_redirect.eq(redirect)
        m.d.sync += t2_redirect.eq(t1_redirect)
        snap_count = 4
        ptr_w = 2
        enq_flag = Signal(name="snpt_enq_flag", init=0)
        enq_ptr = Signal(ptr_w, name="snpt_enq_ptr", init=0)
        deq_flag = Signal(name="snpt_deq_flag", init=0)
        deq_ptr = Signal(ptr_w, name="snpt_deq_ptr", init=0)
        snpt_valids = [Signal(name=f"snpt_valid_{s}", init=0) for s in range(snap_count)]
        snpt_valids_array = Array(snpt_valids)
        snapshot_data: dict[str, list[list[Signal]]] = {}
        snapshot_cols: dict[str, list[Any]] = {}
        for family in fams:
            family_snapshots = [
                [Signal(preg_width, name=f"snpt_{s}_{family}_{i}", reset_less=True)
                 for i in range(32)]
                for s in range(snap_count)
            ]
            snapshot_data[family] = family_snapshots
            snapshot_cols[family] = [
                Array([family_snapshots[s][i] for s in range(snap_count)])
                for i in range(32)
            ]
        enq = self.signals["io_snpt_snptEnq"]
        deq = self.signals["io_snpt_snptDeq"]
        use_snpt = self.signals["io_snpt_useSnpt"]
        snpt_select = self.signals["io_snpt_snptSelect"]
        flush_vec = [self.signals[f"io_snpt_flushVec_{i}"] for i in range(snap_count)]
        full = (enq_flag != deq_flag) & (enq_ptr == deq_ptr)
        with _if_context(m, ~t1_redirect & ~full & enq):
            for fam in fams:
                for i in range(32):
                    m.d.sync += snapshot_cols[fam][i][enq_ptr].eq(spec_tables[fam][i])
            m.d.sync += snpt_valids_array[enq_ptr].eq(Const(1, 1))
            nv, nf = _ptr_add(enq_flag, enq_ptr, 1, snap_count)
            m.d.sync += enq_ptr.eq(nv)
            m.d.sync += enq_flag.eq(nf)
        with _if_context(m, ~t1_redirect & deq):
            m.d.sync += snpt_valids_array[deq_ptr].eq(Const(0, 1))
            nv, nf = _ptr_add(deq_flag, deq_ptr, 1, snap_count)
            m.d.sync += deq_ptr.eq(nv)
            m.d.sync += deq_flag.eq(nf)
        for s in range(snap_count):
            with _if_context(m, flush_vec[s]):
                m.d.sync += snpt_valids[s].eq(Const(0, 1))

        t2_use = Signal(name="t2_useSnpt", init=0)
        t2_select = Signal(2, name="t2_snptSelect", init=0)
        m.d.sync += t2_use.eq(Mux(redirect, Const(0, 1), use_snpt))
        m.d.sync += t2_select.eq(snpt_select)

        is_commit = self.signals["io_rabCommits_isCommit"]
        is_walk = self.signals["io_rabCommits_isWalk"]
        for pos in range(commit_width):
            commit_valid = self.signals[f"io_rabCommits_commitValid_{pos}"]
            walk_valid = self.signals[f"io_rabCommits_walkValid_{pos}"]
            ldest = self.signals[f"io_rabCommits_info_{pos}_ldest"]
            pdest = self.signals[f"io_rabCommits_info_{pos}_pdest"]
            for fam, wen_field in (("int", "rfWen"), ("fp", "fpWen"), ("vec", "vecWen")):
                dest_valid = self.signals[f"io_rabCommits_info_{pos}_{wen_field}"]
                arch_wen = is_commit & commit_valid & dest_valid
                spec_wen = is_walk & walk_valid & dest_valid
                with _if_context(m, arch_wen):
                    m.d.sync += _array_value(arch_tables[fam], ldest).eq(pdest)
                hit_arch = arch_wen & (Array(arch_tables[fam])[ldest])
                del hit_arch
                rename_wen = self.signals.get(f"io_{fam}RenamePorts_{pos}_wen")
                rename_addr = self.signals.get(f"io_{fam}RenamePorts_{pos}_addr")
                rename_data = self.signals.get(f"io_{fam}RenamePorts_{pos}_data")
                wen = Mux(rename_wen if rename_wen is not None else Const(0, 1),
                          Const(1, 1), spec_wen)
                waddr = Mux(rename_wen if rename_wen is not None else Const(0, 1),
                            rename_addr[:addr_w] if rename_addr is not None else ldest,
                            ldest)
                wdata = Mux(rename_wen if rename_wen is not None else Const(0, 1),
                            rename_data if rename_data is not None else pdest, pdest)
                key = f"{fam}_{pos}"
                t1_wen[key] = Signal(name=f"t1_wen_{key}", init=0)
                t1_waddr[key] = Signal(addr_w, name=f"t1_waddr_{key}", init=0)
                t1_wdata[key] = Signal(preg_width, name=f"t1_wdata_{key}", init=0)
                m.d.sync += t1_wen[key].eq(Mux(redirect, Const(0, 1), wen))
                m.d.sync += t1_waddr[key].eq(waddr)
                m.d.sync += t1_wdata[key].eq(wdata)
        for fam in fams:
            for i in range(32):
                match: Value = Const(0, 1)
                data: Value = Const(0, preg_width)
                for pos in range(commit_width):
                    key = f"{fam}_{pos}"
                    hit = t1_wen[key] & (t1_waddr[key] == i)
                    data = Mux(hit, t1_wdata[key], data)
                    match = match | hit
                recovered = Mux(t2_use,
                                snapshot_cols[fam][i][t2_select],
                                Array(arch_tables[fam])[i])
                m.d.sync += spec_tables[fam][i].eq(
                    Mux(t2_redirect, recovered, Mux(match, data, spec_tables[fam][i])))

        # Read ports: slice the wide one-hot-style address buses down to the
        # table's binary address exactly as the pinned connections show.
        # 读口：按钉死连接把宽地址总线切到表的二进制地址。
        for fam in fams:
            for k in sorted(self.signals):
                if not k.startswith(f"io_{fam}ReadPorts_") or not k.endswith("_addr"):
                    continue
                base = k[:-len("_addr")]
                addr = self.signals[k]
                data = self.signals[base + "_data"]
                hold = self.signals.get(base + "_hold", Const(0, 1))
                t1_raddr = Signal(addr_w, name=f"t1_raddr_{base}", init=0)
                m.d.sync += t1_raddr.eq(Mux(hold, t1_raddr, addr[:addr_w]))
                m.d.comb += data.eq(Array(spec_tables[fam])[t1_raddr])
            for pos in range(commit_width):
                op = self.signals.get(f"io_{fam}_old_pdest_{pos}")
                if op is not None:
                    m.d.comb += op.eq(Const(0, preg_width))
                nf = self.signals.get(f"io_{fam}_need_free_{pos}")
                if nf is not None:
                    m.d.comb += nf.eq(Const(0, 1))

        # v0/vl single-entry maps. / v0/vl 单表项映射。
        v_regs: dict[str, Signal] = {}
        for fam in ("v0", "vl"):
            v_reg = Signal(preg_width, name=f"{fam}_spec", init=0, reset_less=True)
            v_regs[fam] = v_reg
            for k in sorted(self.signals):
                if k.startswith(f"io_{fam}RenamePorts_") and k.endswith("_wen"):
                    pos = k[len(f"io_{fam}RenamePorts_"):-len("_wen")]
                    wen = self.signals[k]
                    wdata = self.signals[f"io_{fam}RenamePorts_{pos}_data"]
                    with _if_context(m, wen):
                        m.d.sync += v_reg.eq(wdata)
            for k in sorted(self.signals):
                if k.startswith(f"io_{fam}ReadPorts_") and k.endswith("_data"):
                    m.d.comb += self.signals[k].eq(v_reg)
            for pos in range(commit_width):
                out_name = f"io_{fam}_old_pdest_{pos}"
                if out_name in self.signals:
                    m.d.comb += self.signals[out_name].eq(Const(0, preg_width))
                nf_name = f"io_{fam}_need_free_{pos}"
                if nf_name in self.signals:
                    m.d.comb += self.signals[nf_name].eq(Const(0, 1))
        for i in range(int(p.get("numDiffRatBase") or 0)):
            pass
        # Difftest VL mapping view: single-entry vl register.
        # Difftest VL 映射视图：单表项 vl 寄存器。
        for k in sorted(self.signals):
            if k.startswith("io_diff_") and self.dirs.get(k) == "output":
                src = v_regs.get("vl") if "vl" in k else None
                if src is None:
                    m.d.comb += self.signals[k].eq(Const(0, self.signals[k].width))
                else:
                    m.d.comb += self.signals[k].eq(src)
        del ldest_w, redirect

    def _elab_Unknown(self, m: Module) -> None:
        # Unknown members keep their locked port surface unmodified.
        # 未知成员保持锁定端口面不变。
        del m


# =============================================================================
# Public Adapter
# =============================================================================
# Deterministic Amaranth Verilog export for one module or the whole family.
# 面向单模块或整个家族的确定性 Amaranth Verilog 导出。
def build_verilog(configuration, injected_dependencies):
    config: dict[str, Any] = configuration if isinstance(configuration, dict) else {}
    del injected_dependencies
    only = config.get("module")
    top_name = str(config.get("top_name") or only or "UHSCBackendRegfileFamily")
    specs = _specs()
    names = [str(only)] if only is not None else sorted(specs)
    emitted: list[str] = []
    for name in names:
        if name not in specs:
            continue
        mod = PortedModule(name)
        ports = [mod.signals[k] for k in sorted(mod.signals)]
        text = verilog.convert(mod, name=str(config.get("top_name") or name)
                               if only is not None else name, ports=ports)
        start = text.index("module")
        end = text.rindex("endmodule") + len("endmodule")
        emitted.append(text[start:end])
    prefix = "/* V2 regfile/rename-snapshot/writeback-arbitration family, "
    prefix += "Amaranth-generated. */\n"
    prefix += "`timescale 1ns/1ps\n`default_nettype none\n"
    return prefix + "\n".join(emitted) if top_name else prefix


# =============================================================================
# Direct Entry
# =============================================================================
# Print the default full-family export. / 打印默认整族导出结果。
def main() -> None:
    print(build_verilog(None, None))


if __name__ == "__main__":
    main()
